import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Architecture & layout — M1 (for review)","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/reports/2026-10-27-architecture-m1.md","filePath":"vendored/graphopt/project/reports/2026-10-27-architecture-m1.md"}`),a={name:`graphopt/project/reports/2026-10-27-architecture-m1.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="architecture-layout-—-m1-for-review" tabindex="-1">Architecture &amp; layout — M1 (for review) <a class="header-anchor" href="#architecture-layout-—-m1-for-review" aria-label="Permalink to “Architecture &amp; layout — M1 (for review)”">​</a></h1><p><strong>Form:</strong> lab (ADR-0159 not yet triggered). Repos, drivers and own harnesses; no <code>ext</code> wrapper, no FFI seam. <strong>Naming:</strong> <code>opt-graph</code> (today <code>graphopt</code>), <code>opt-kernel</code> (today <code>kernelopt</code>); the IR is ADR-0160.</p><h2 id="corrections-from-review-accepted" tabindex="-1">Corrections from review (accepted) <a class="header-anchor" href="#corrections-from-review-accepted" aria-label="Permalink to “Corrections from review (accepted)”">​</a></h2><p><strong>1. <code>lib-kernel-ir</code> was the wrong noun.</strong> A <strong>kit</strong> is a curated manifest of handl libs; a <strong>lib</strong> is a package. So the vocabulary is <strong><code>lib-kernel-ir</code></strong> (a handl library: ops, grades, costs, denotations), and <strong><code>kit-kernel-ir</code> (M2)</strong> is the curated kit that includes it alongside the base types. Two artefacts, two nouns, as every other kit/lib pair in the org.</p><p><strong>2. <code>compile-triton</code> is Rust.</strong> Every engine in the <code>compile-*</code> family is Rust; emitting Triton is string generation over a term, so it belongs there too — deterministic, no Python runtime, part of the engine family. Executing the emitted source needs Python, but that is the runtime binding (<code>lib-triton-qgemv</code>) or an ext, never the compiler.</p><p><strong>3. There is no new schema. The IR <em>is</em> <code>Term</code>.</strong> This is the correction that matters: handl already represents computation as data — <code>Term::{Arr, Seq, Op, Handle, Loop, App}</code> with a dimension/grade slot. A schedule does not need a parallel IR format; it needs <strong>ops the kit declares</strong> (<code>tile_load</code>, <code>split</code>, <code>dot</code>, …), carried in <code>Term::Op</code> with a grade row, and <strong>an engine that interprets them</strong>. So:</p><table tabindex="0"><thead><tr><th>before (wrong)</th><th>after (right)</th></tr></thead><tbody><tr><td>new <code>KernelIR</code> schema in <code>lib-kernel-ir</code></td><td><strong><code>Term</code> values</strong> with kit-declared ops</td></tr><tr><td>IR → Triton lowering in a bespoke module</td><td><strong><code>compile-triton</code></strong> interprets <code>Term</code></td></tr><tr><td>denotations in the kit</td><td>denotations in <strong><code>lib-kernel-ir</code></strong> tests + laws</td></tr></tbody></table><p>What this buys: the body is transparent <strong>in the platform&#39;s own representation</strong>, so the certificate, the sink, the sieve and the cost model all apply unchanged — no second universe to keep in sync. Where a schedule cannot be expressed as <code>Term</code>, that is a finding about the calculus, and the platform&#39;s rule applies: it enters by data (an op), a desugaring, or a handler — never by a new combinator.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>                 ┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>                 │  lib-kernel-ir      (DATA: the IR vocabulary)  │</span></span>
<span class="line"><span>                 │  ops: tile_load unpack_i4 dequant dot split │</span></span>
<span class="line"><span>                 │        stage reduce store bias              │</span></span>
<span class="line"><span>                 │  each: signature · grade row · cost · law   │</span></span>
<span class="line"><span>                 └───────────────────┬─────────────────────────┘</span></span>
<span class="line"><span>                                     │  IR terms (schedules as data)</span></span>
<span class="line"><span>                 ┌───────────────────▼─────────────────────────┐</span></span>
<span class="line"><span>                 │  opt-kernel  (SEARCH + CERTIFICATE)         │</span></span>
<span class="line"><span>                 │  enumerate terms → legality → roofline floor│</span></span>
<span class="line"><span>                 │  → equality gate → deploy-referee timing    │</span></span>
<span class="line"><span>                 └──────┬───────────────────────────┬──────────┘</span></span>
<span class="line"><span>                        │ term                      │ chosen term</span></span>
<span class="line"><span>        ┌───────────────▼────────────┐   ┌──────────▼───────────────┐</span></span>
<span class="line"><span>        │ compile-triton (LOWERING)  │   │ graphopt/bench (REFEREE) │</span></span>
<span class="line"><span>        │ term → Triton source       │   │ regime.py: eviction,     │</span></span>
<span class="line"><span>        │ one op, 4 split_k variants │   │ blocked rounds, roofline │</span></span>
<span class="line"><span>        └───────────────┬────────────┘   └──────────────────────────┘</span></span>
<span class="line"><span>                        │ source</span></span>
<span class="line"><span>        ┌───────────────▼────────────┐</span></span>
<span class="line"><span>        │ lib-triton-qgemv             │   (M2 — needed to ship,</span></span>
<span class="line"><span>        │ runtime binding + manifest │    not to find)</span></span>
<span class="line"><span>        └────────────────────────────┘</span></span></code></pre></div><p><strong>Two-stage schedule, stated once:</strong> our IR decides blocks and split; Triton decides pipelining, vectorization and layouts. Reports must say which stage chose what, or a win cannot be attributed.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handl-lang/</span></span>
<span class="line"><span>├── \`kernelopt\` (ADR)</span></span>
<span class="line"><span>│   └── 01XX-kernel-ir-as-language.md      ← (1) ADR: IR is data, kernel stays closed</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── lib-kernel-ir/                          ← (2) NEW · the vocabulary (data)</span></span>
<span class="line"><span>│   ├── fragments/</span></span>
<span class="line"><span>│   │   ├── qgemv.yaml                     op · signature · grades · cost</span></span>
<span class="line"><span>│   │   └── _ops.yaml                      the nine core ops</span></span>
<span class="line"><span>│   ├── denotations/                       (3) torch reference per op</span></span>
<span class="line"><span>│   │   ├── qgemv.py</span></span>
<span class="line"><span>│   │   └── _shared.py</span></span>
<span class="line"><span>│   └── tests/</span></span>
<span class="line"><span>│       └── test_denotations.py            every op has a reference + a shape</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── kit-kernel-ir/ (M2)                               ← curated kit: includes lib-kernel-ir</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── compile-triton/                         ← (4) NEW · Rust engine (lowering)</span></span>
<span class="line"><span>│   ├── src/</span></span>
<span class="line"><span>│   │   ├── lower.py                       term → Triton source</span></span>
<span class="line"><span>│   │   └── variants.py                    split_k ∈ {1,2,4,8}</span></span>
<span class="line"><span>│   └── tests/</span></span>
<span class="line"><span>│       └── test_lower_qgemv.py            compile + run + compare</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── kernelopt/                              ← (6) SEARCH (exists, extend)</span></span>
<span class="line"><span>│   └── packages/mlopt-kernel/src/mlopt_kernel/</span></span>
<span class="line"><span>│       ├── schedules.py                   (NEW) IR terms as data</span></span>
<span class="line"><span>│       └── search.py                      (NEW) enumerate → gate → measure</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── graphopt/bench/                         ← (5) REFEREE (exists)</span></span>
<span class="line"><span>│   ├── benchkit/regime.py                 eviction · blocked rounds · roofline</span></span>
<span class="line"><span>│   └── drivers/probes/awq/                incumbents: hand kernel, awq_gemm,</span></span>
<span class="line"><span>│                                          the probes that produced P13–P18</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── lib-triton-qgemv/                        ← M2 · runtime binding (deferred)</span></span></code></pre></div><h2 id="what-each-piece-owns" tabindex="-1">What each piece owns <a class="header-anchor" href="#what-each-piece-owns" aria-label="Permalink to “What each piece owns”">​</a></h2><table tabindex="0"><thead><tr><th>layer</th><th>owns</th><th>does not own</th></tr></thead><tbody><tr><td><code>lib-kernel-ir</code> (+ <code>kit-kernel-ir</code> (M2))</td><td>op vocabulary, grades, costs, denotations</td><td>code generation, measurement</td></tr><tr><td><code>compile-triton</code></td><td>term → Triton, one op at a time</td><td>choosing which term</td></tr><tr><td><code>kernelopt</code></td><td>enumeration, legality, certificates, the choice</td><td>the lowering, the referee</td></tr><tr><td><code>graphopt/bench</code></td><td>the honest number</td><td>the search, the semantics</td></tr><tr><td><code>lib-triton-qgemv</code></td><td>running the winner in a host</td><td>finding it</td></tr></tbody></table><h2 id="m1-boundary" tabindex="-1">M1 boundary <a class="header-anchor" href="#m1-boundary" aria-label="Permalink to “M1 boundary”">​</a></h2><p><strong>In:</strong> ADR · <code>lib-kernel-ir</code> with nine ops + denotations · <code>kit-kernel-ir</code> (M2) manifest · <code>compile-triton</code> for <code>qgemv</code> with 4 <code>split_k</code> variants · equality gate vs <code>awq_gemm</code> · search driver emitting a best kernel and a routing row.</p><p><strong>Out:</strong> <code>lib-triton-qgemv</code> binding, M&gt;1 tiling, FP8/GPTQ, compile cache, <code>compile-cuda</code>, cost-model <em>ranking</em> (bound only).</p><p><strong>Gate:</strong> all four variants cosine ≥ 0.9999 vs <code>awq_gemm</code>; at least one within the hand kernel&#39;s 58.9 µs cold on <code>down_proj</code>.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};